/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `wp_arsenal_match_statuses_generate_id` BEFORE INSERT ON `wp_arsenal_match_statuses` FOR EACH ROW BEGIN 

    IF NEW.status_id IS NULL THEN 

        SET NEW.status_id = UPPER(SUBSTR(MD5(UPPER(TRIM(NEW.match_status))), 1, 8)); 

    END IF; 

END */;;
