/*!40000 ALTER TABLE `wp_arsenal_matches` ENABLE KEYS */;
UNLOCK TABLES;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_unicode_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `wp_arsenal_matches_generate_id` BEFORE INSERT ON `wp_arsenal_matches` FOR EACH ROW BEGIN 

    IF NEW.match_id IS NULL THEN 

        SET NEW.match_id = UPPER(SUBSTR(MD5(CONCAT(NEW.home_team_id, NEW.away_team_id, NEW.match_date)), 1, 8)); 

    END IF; 

END */;;
DELIMITER ;
