/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `wp_arsenal_seasons_generate_id` BEFORE INSERT ON `wp_arsenal_seasons` FOR EACH ROW BEGIN 

    IF NEW.season_id IS NULL THEN 

        SET NEW.season_id = UPPER(SUBSTR(MD5(UPPER(TRIM(NEW.season_name))), 1, 8)); 

    END IF; 

END */;;
